A graph can be represented using an adjacency list. Here's a basic implementation of DFS:

```python
class Graph:
    def __init__(self):
        self.graph = {}

    def add_edge(self, u, v):
        if u in self.graph:
            self.graph[u].append(v)
        else:
            self.graph[u] = [v]

    def dfs(self, start, goal):
        visited = set()
        stack = [start]
        while stack:
            node = stack.pop()
            if node == goal:
                return True
            if node not in visited:
                visited.add(node)
                for neighbor in self.graph.get(node, []):
                    stack.append(neighbor)
        return False

